-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLPool.json. Do not edit: change the chain file or ABI and regenerate.
-- Swap(address,address,int256,int256,uint160,uint128,int24)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_pool__swap',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as sender,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as recipient,
    reinterpretAsInt256(reverse(unhex(substring(data, 3, 64)))) as amount0,
    reinterpretAsInt256(reverse(unhex(substring(data, 67, 64)))) as amount1,
    reinterpretAsUInt256(reverse(unhex(substring(data, 131, 64)))) as sqrt_price_x96,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 195, 64))))) as liquidity,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(data, 259, 64))))) as tick
from {{ source('chain_base', 'logs') }}
where topic0 = '0xc42079f94a6350d7e6235f29174924f928cc2ac818eb64fed8004e115fbcca67'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
